<script>
(() => {
  const menu = document.getElementById('nav');
  const menuToggle = document.getElementById('menuToggle');
  const langToggle = document.getElementById('langToggle');
  let lang = <?= json_encode($lang) ?>;

  menuToggle.addEventListener('click', () => {
    const open = menu.classList.toggle('open');
    menuToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  });
  menu.querySelectorAll('a').forEach(a => a.addEventListener('click', () => menu.classList.remove('open')));

  function setLang(next){
    lang = next;
    document.documentElement.lang = next;
    document.querySelectorAll('[data-en][data-ru]').forEach(el => el.textContent = el.dataset[next]);
    langToggle.textContent = next === 'en' ? 'EN⌄' : 'RU⌄';
  }
  langToggle.addEventListener('click', () => { const next = lang === 'en' ? 'ru' : 'en'; window.location.search = '?lang=' + next; });
  setLang(lang);
})();
</script>
